.recall-experiment { position: relative; padding: 28px 28px 30px 43px; background-color: #f7eeeb; background-image: linear-gradient(90deg, transparent 24px, #d7a59e 24px, #d7a59e 25px, transparent 25px); border-radius: 2px 3px 8px 1px; box-shadow: 2px 4px 10px rgb(0 0 0 / .1); }
.recall-experiment::before { content: ''; position: absolute; left: 9px; top: 28px; bottom: 25px; width: 6px; background-image: radial-gradient(circle, #6d5a54 2px, transparent 2.6px); background-size: 6px 30px; }
.recall-steps { display: grid; grid-template-columns: .85fr 1.3fr .85fr; list-style: none; gap: 9px; padding: 0 0 24px; margin: 0; }
.recall-steps li { position: relative; text-align: center; font-size: 13px; font-weight: 500; line-height: 1.3; padding: 11px 3px; border: 1px solid #ad8d83; border-radius: 38% 5% 20% 6% / 8% 36% 7% 30%; }
.recall-steps li:nth-child(2) { transform: rotate(2deg); }
.recall-steps li[aria-current=step] { color: #91281f; font-weight: 700; border: 2px solid #b3342a; padding: 10px 2px; background: #fffdf7; }
.recall-instruction { min-height: 45px; }
.recall-stage { min-height: 174px; }
@media (max-width: 1100px) and (min-width: 768px) {
  .recall-experiment { padding-right: 22px; padding-left: 36px; }
  .recall-steps { gap: 5px; }
  .recall-steps li { font-size: 12px; }
}
@media (max-width: 767px) {
  .recall-experiment { padding: 24px 20px 27px 35px; }
  .recall-steps { gap: 5px; padding-bottom: 22px; }
  .recall-steps li { font-size: 12px; }
  .recall-stage { min-height: 174px; }
  .recall-words { font-size: 33px; }
  .recall-controls .button { padding-inline: 14px; font-size: 12px; gap: 10px; }
}
@media (max-width: 359px) {
  .recall-experiment { padding-left: 32px; padding-right: 16px; }
  .recall-steps { grid-template-columns: .8fr 1.25fr .85fr; }
  .recall-steps li { font-size: 12px; }
  .recall-words { font-size: 28px; }
  .recall-controls .button { padding-inline: 11px; gap: 7px; font-size: 12px; }
}

:host{font-family:"Bricolage Grotesque Variable",sans-serif;--paper:#f7f6f2;--surface:#fffefd;--ink:#242323;--muted:#615d5a;--rule:#d4cfcb;--accent:#b3342a;--button:#b3342a;--tint:#f3e9e5;--ease-out:cubic-bezier(.23,1,.32,1);color:var(--ink)}*{box-sizing:border-box}[hidden]{display:none!important}p,h3,ul{margin:0}p{line-height:1.7}button,input,textarea{font:inherit}button{cursor:pointer}:focus-visible{outline:3px solid var(--accent);outline-offset:5px}

.workshop-section { background: #252221; color: #f8f4f0; --paper: #252221; --surface: #302b29; --ink: #f8f4f0; --muted: #d3c9c1; --rule: #5b504b; --accent: #f18c7e; --tint: #352c29; }
.workshop summary { display: flex; justify-content: space-between; gap: 20px; align-items: center; padding: 23px 0; cursor: pointer; list-style: none; }
.workshop summary > .ph { font-size: 24px; }
.workshop-name { display: flex; flex-direction: column; gap: 9px; font-size: clamp(26px, 2.7vw, 36px); line-height: 1.16; letter-spacing: -.025em; font-weight: 600; }
.workshop-name > span { font-size: 13px; color: var(--muted); letter-spacing: 0; font-weight: 450; }
.workshop[open] > summary { color: var(--accent); }
.workshop[open] > summary > .ph-plus { transform: rotate(45deg); }
.workshop-content { font-size: 16px; padding-bottom: 26px; }
.workshop-content > p { color: var(--muted); max-width: 48ch; margin-bottom: 18px; }
.workshop-content ul { font-size: 16px; }
.workshop-section :focus-visible { outline-color: #f18c7e; }

@media (hover: hover) and (pointer: fine) {
  .workshop > summary:hover { color: var(--accent); }
}
@media (max-width: 767px) {
  .workshop summary { padding-block: 22px; }
  .workshop-name { font-size: 28px; }
  .workshop-name > span { font-size: 13px; }
  .workshop-content { padding-bottom: 24px; }
}

:host{font-family:"Bricolage Grotesque Variable",sans-serif;--accent:#b3342a;--drawing-paper:#fffdf7;color:#242323}
.ink-drawing { display: block; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; pointer-events: none; }
.ink-drawing .red-pen { stroke: var(--accent); }
.ink-drawing text { stroke: none; fill: currentColor; font: 650 22px 'Bricolage Grotesque Variable', sans-serif; }
.question-comic { position: absolute; z-index: 2; width: 185px; right: -3px; top: 13px; transform: rotate(9deg); pointer-events: none; }
.comic-fill { fill: var(--drawing-paper); }
@media (max-width: 1100px) and (min-width: 768px) {
  .question-comic { width: 145px; top: 3px; right: -7px; }
}
@media (max-width: 767px) {
  .question-comic { width: 124px; top: 0; right: 0; transform: rotate(7deg); }
  .question-comic text { font-size: 23px; }
}
